def new(title,scope):
    d=Document(); s=d.sections[0]
    s.page_width=Inches(8.5); s.page_height=Inches(11)
    s.top_margin=s.bottom_margin=Inches(.65);s.left_margin=s.right_margin=Inches(.75)
    for name in ['Normal','Title','Subtitle','Heading 1','Heading 2','Caption']:
        st=d.styles[name];st.font.name='Tahoma';st.font.color.rgb=RGBColor(0,0,0)
        st.element.get_or_add_rPr().rFonts.set(qn('w:eastAsia'),'Tahoma')
        st.element.get_or_add_rPr().rFonts.set(qn('w:cs'),'Tahoma')
        st.font.size=Pt(11 if name=='Normal' else 10 if name=='Caption' else 24 if name=='Title' else 16 if name=='Heading 1' else 12)
    n=d.styles['Normal'].paragraph_format;n.space_after=Pt(7);n.line_spacing=1.15
    d.add_paragraph(title,'Title'); d.add_paragraph('Upper House Residences Hong Kong Private Preview','Subtitle')
    p(d,scope);p(d,'ฉบับอ้างอิงวันที่ 15 ตุลาคม 2569  |  กิจกรรมวันที่ 14–15 พฤศจิกายน 2026')
    foot=s.footer.paragraphs[0];foot.text='UH Registration  •  คู่มือภาษาไทย  •  หน้า '
    field=OxmlElement('w:fldSimple');field.set(qn('w:instr'),'PAGE');foot._p.append(field)
    return d
def p(d,t):d.add_paragraph(t)
def h(d,t):d.add_heading(t,1)
def page(d,t):d.add_page_break();h(d,t)
def steps(d,items):
    for i,t in enumerate(items,1):p(d,f'{i}. {t}')
def pic(d,name,caption,w=6.5,maxh=3.8):
    path=IMG/name;im=Image.open(path);w=min(w,maxh*im.width/im.height)
    pa=d.add_paragraph();pa.paragraph_format.keep_with_next=True;pa.alignment=1
    pa.add_run().add_picture(str(path),width=Inches(w));d.add_paragraph(caption,'Caption')
def table(d,headers,rows):
    t=d.add_table(rows=1,cols=len(headers));t.style='Table Grid'
    for c,txt in zip(t.rows[0].cells,headers):c.text=txt
    for row in rows:
        for c,txt in zip(t.add_row().cells,row):c.text=str(txt)
    for c in t.rows[0].cells:
        pr=c._tc.get_or_add_tcPr();sh=OxmlElement('w:shd');sh.set(qn('w:fill'),'E7EBED');pr.append(sh)
        for r in c.paragraphs[0].runs:r.bold=True
    d.add_paragraph()

